#import "TFAIAppActions.h"
static NSDictionary *Actions(void){return @{
 @"list_connections":@[],@"select_connection":@[@"connection_id"],@"update_connection":@[@"connection_id",@"changes"],
 @"read_git_preferences":@[],@"set_git_preferences":@[@"changes"],@"git_conflicts":@[],@"git_read_conflict":@[@"path",@"side"],@"git_resolve_conflict":@[@"path",@"choice",@"fingerprint",@"state_token"],@"git_finish_merge":@[@"message",@"state_token"],@"git_abort_merge":@[@"state_token"],@"git_merge_branch":@[@"branch",@"state_token"],@"git_initialize":@[],@"git_branches":@[],@"git_branch":@[@"branch",@"operation"],@"git_set_remote":@[@"url"],
 @"storage_clean":@[@"item_ids"],@"storage_summary":@[],@"storage_list":@[@"category"],
 @"list_session_files":@[],@"read_session_file":@[@"resource_id"],@"session_info":@[],@"session_rename":@[@"title"],@"session_pin":@[@"pinned"],
 @"open_model_controls":@[],@"open_permissions":@[],@"choose_attachment":@[],@"open_settings":@[],@"open_ai_settings":@[],@"open_storage":@[],@"open_session_files":@[]};}
static BOOL IsRead(NSString *action){return [@[@"list_connections",@"read_git_preferences",@"git_branches",@"git_conflicts",@"git_read_conflict",@"storage_summary",@"storage_list",@"session_info",@"list_session_files",@"read_session_file"] containsObject:action];}
static NSError *Failure(NSString *reason){return [NSError errorWithDomain:@"Dylix.AppAction" code:1 userInfo:@{NSLocalizedDescriptionKey:reason}];}
NSArray *TFAIActionSchemas(BOOL readOnly){NSMutableArray *names=[NSMutableArray new];for(NSString *key in Actions())if(!readOnly||IsRead(key))[names addObject:key];return @[@{@"name":@"app_action",@"description":@"Invoke real Dylix services. Discover action names and parameter requirements in read_app_state. list/update/select saved connections (no keys); global Git preferences; initialize/list/create/switch/delete Git branches and set HTTPS remote; inspect storage and clean selected cached items; list/read shared session resources; rename/pin current session; open native settings, AI settings, storage, session files. Mutations require approval. Changes to connections apply to the next turn. Native pages require foreground. Project actions require current workspace. This is NOT arbitrary code/defaults execution.",@"parameters":@{@"type":@"object",@"properties":@{@"action":@{@"type":@"string",@"enum":[names sortedArrayUsingSelector:@selector(compare:)]},@"item_ids":@{@"type":@"array",@"items":@{@"type":@"string"},@"minItems":@1,@"maxItems":@50},@"path":@{@"type":@"string"},@"side":@{@"type":@"string"},@"choice":@{@"type":@"string"},@"fingerprint":@{@"type":@"string"},@"state_token":@{@"type":@"string"},@"message":@{@"type":@"string"},@"text":@{@"type":@"string"},@"resource_id":@{@"type":@"string"},@"start_line":@{@"type":@"integer",@"minimum":@1},@"connection_id":@{@"type":@"string"},@"changes":@{@"type":@"object"},@"category":@{@"type":@"string"},@"offset":@{@"type":@"integer",@"minimum":@0},@"branch":@{@"type":@"string"},@"operation":@{@"type":@"string",@"enum":@[@"create",@"checkout",@"delete"]},@"url":@{@"type":@"string"},@"title":@{@"type":@"string"},@"pinned":@{@"type":@"boolean"}},@"required":@[@"action"],@"additionalProperties":@NO}}];}
BOOL TFAIActionValidate(NSDictionary *args,BOOL *write,NSError **error){
 if(![args isKindOfClass:NSDictionary.class]||![args[@"action"] isKindOfClass:NSString.class]){if(error)*error=Failure(@"请提供应用操作名称");return NO;}NSString *action=args[@"action"];NSArray *required=Actions()[action];if(!required){if(error)*error=Failure(@"未知应用操作，请先 read_app_state");return NO;}
 NSMutableSet *allowed=[NSMutableSet setWithArray:required];[allowed addObject:@"action"];if([@[@"storage_list",@"list_session_files",@"git_conflicts"] containsObject:action])[allowed addObject:@"offset"];if([@[@"read_session_file",@"git_read_conflict"] containsObject:action])[allowed addObject:@"start_line"];
 if([action isEqual:@"git_resolve_conflict"])[allowed addObject:@"text"];for(NSString *key in args){id value=args[key];BOOL valid=[allowed containsObject:key];if([key isEqual:@"item_ids"]){valid=valid&&[value isKindOfClass:NSArray.class]&&[value count]>0&&[value count]<=50;for(id item in (valid?value:@[]))if(![item isKindOfClass:NSString.class]||![item length]||[item length]>128)valid=NO;}else if([key isEqual:@"changes"])valid=valid&&[value isKindOfClass:NSDictionary.class]&&[value count]>0;else if([key isEqual:@"pinned"])valid=valid&&[value isKindOfClass:NSNumber.class]&&CFGetTypeID((__bridge CFTypeRef)value)==CFBooleanGetTypeID();else if(([key isEqual:@"offset"]||[key isEqual:@"start_line"]))valid=valid&&[value isKindOfClass:NSNumber.class]&&[value doubleValue]==[value integerValue]&&[value integerValue]>=0;else valid=valid&&[value isKindOfClass:NSString.class]&&([value length]>0||[key isEqual:@"text"])&&[value length]<=([key isEqual:@"text"]?262144:2048);if(!valid){if(error)*error=Failure([@"操作参数无效：" stringByAppendingString:key]);return NO;}}
 for(NSString *key in required)if(!args[key]){if(error)*error=Failure([@"缺少参数：" stringByAppendingString:key]);return NO;}if(args[@"start_line"]&&[args[@"start_line"] integerValue]<1){if(error)*error=Failure(@"起始行应大于零");return NO;}if(write)*write=!IsRead(action);return YES;
}
NSDictionary *TFAIActionCatalog(BOOL readOnly){NSMutableDictionary *actions=[NSMutableDictionary new];for(NSString *name in Actions())if(!readOnly||IsRead(name))actions[name]=@{@"required":Actions()[name],@"mutates":@(!IsRead(name))};return @{
 @"actions":actions,
 @"connectionChanges":@{@"name":@"string <=256",@"model":@"string <=256",@"toolsEnabled":@"boolean",@"thinkingOverrides":@"object: preserve existing keys; see thinkingOverrides documentation"},
 @"thinkingOverrides":@"changes.thinkingOverrides uses the connection editor existing map format: endpoint/protocol/model key -> {wire:reasoning_effort|reasoning|thinking|enable_thinking|thinking_budget|chat_template_kwargs|anthropic_budget|anthropic_adaptive|gemini_budget|gemini_level|disabled,levels:[none|minimal|low|medium|high|xhigh|ultra|max|enabled]}. Read existing values first. Prefer open_model_controls for selecting effort in the current conversation. open_permissions opens the app approval UI; tools never grant themselves permission. choose_attachment opens the existing picker after this run finishes.",@"gitConflicts":@"git_conflicts returns state_token and per-file fingerprint. Read base/ours/theirs in pages via git_read_conflict. Resolve with choice ours|theirs|manual, path, fingerprint, state_token and manual text. Refresh after each mutation. Finish via git_finish_merge only after zero conflicts; no upload. git_abort_merge uses native backup before abort; git_merge_branch starts a merge. Every mutation requires explicit confirmation.",@"gitChanges":@[@"name",@"email",@"enabled",@"afterSave",@"afterBuild",@"protect",@"delay",@"template"],
 @"storageCleanup":@"storage_list returns opaque item_id, category and actual size. storage_clean takes selected item_ids and requests explicit approval. It rechecks item fingerprints. Only cache, temporary, exports and trash are exposed for AI cleanup; use clean_builds for project builds and native storage UI for attachments/IPA/headers currently usable by conversations.",@"sessionResources":@"list_session_files returns opaque resource_id values for the SAME files shown by the app, with dates and source. read_session_file returns bounded text, 120 lines/16KB. Do not invent paths."};}
